def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c, k):
        if c.islower() and k.islower():
            return chr((ord(c) - ord(k) + 26) % 26 + ord('a'))
        elif c.isupper() and k.isupper():
            return chr((ord(c) - ord(k) + 26) % 26 + ord('A'))
        else:
            return c

    key_length = len(key)
    key_as_int = [ord(i) for i in key]
    ciphertext_int = [ord(i) for i in ciphertext]
    plaintext = ''

    for i in range(len(ciphertext_int)):
        value = (ciphertext_int[i] - key_as_int[i % key_length]) % 26
        plaintext += chr(value + 65) if ciphertext[i].isupper() else chr(value + 97)

    return plaintext.lower()

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    decrypted_text = []
    key_length = len(key)
    key_as_int = [ord(i) for i in key]
    ciphertext_as_int = [ord(i) for i in ciphertext]

    for i in range(len(ciphertext_as_int)):
        value = (ciphertext_as_int[i] - key_as_int[i % key_length]) % 26
        decrypted_text.append(chr(value + 65))

    return "".join(decrypted_text).lower()

